string Classify(Action action){try{action();return "accepted";}catch(SemanticRefusalException ex){return ex.Code;}catch(InvalidDataException ex){return ex.Message.Split(':')[0];}catch(Exception ex){return ex.GetType().Name+":"+ex.Message;}}
